properties.query:
// Only events ingested since the last run (see tools/build.py)
let CowrieNew = Cowrie_CL | where ingestion_time() > ago(1h);
CowrieNew
| where (eventid =~ "cowrie.login.failed")
| summarize value_count = dcount(password) by bin(TimeGenerated, 10m), src_ip
| where value_count >= 5
